export function localizeNotification(text,language){const map=language==='en'?en:ar;return String(text).split(/(https?:\/\/[^\s<>]+|<[^>]+>)/).map(part=>{if(/^(https?:\/\/|<)/.test(part))return part;for(const key of Object.keys(map).sort((a,b)=>b.length-a.length))if(key&&!key.includes('${'))part=part.split(key).join(map[key]);return part;}).join('');}
